insert into "readiness_pillars" ("pillar_id", "pillar_name", "pillar_description", "pillar_weightage", "pillar_order", "created_at", "updated_at", "what_falls_under", "score_bands", "stage_behaviour", "red_flag_threshold", "red_flag_note") values ('1', 'Founder Readiness', 'Measures the founder as a person — psychological state, self-awareness, resilience, motivation depth, decision-making quality, and capacity to lead under pressure. The single most important variable in startup success.', '25.00', '1', '2026-07-10 11:15:56.284048+00', '2026-07-26 05:27:23.650751+00', '["Intrinsic motivation — why they are building and how deep that drive goes", "Self-awareness — whether they know their strengths, blind spots, and triggers", "Emotional regulation — how they process setbacks, rejection, and uncertainty", "Decision-making quality — how they make big decisions and learn from them", "Resilience and persistence — whether they can sustain effort through long difficult periods", "Identity and founder psychology — imposter syndrome, fear of failure, perfectionism, burnout", "Learning orientation — whether they seek feedback and update their beliefs", "Support structures — whether they have mentors, peers, or a team to lean on"]', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "The founder is psychologically unprepared for the demands of this journey right now. Burnout, identity crisis, deep fear of failure, or isolation are active blockers. Business actions will not move the needle until this is addressed. The report will include Section H (Psychological State Note)."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The founder has the drive but is showing signs of strain — overwork, poor boundaries, reactive decision-making, or self-doubt undermining good execution. Business progress is possible but will be limited until personal sustainability is built."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "The founder is reasonably self-aware, motivated, and functional under pressure. Some blind spots and stress patterns exist but are not blocking growth. This is the most common range for early-stage founders."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "The founder shows deep self-awareness, genuine intrinsic motivation, strong emotional regulation, and high resilience. They seek feedback, make deliberate decisions, and have sustainable work patterns. This is rare and is a genuine competitive advantage."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Motivation clarity and idea conviction are the primary measures. Most founders at this stage score low here because the real psychological challenge of building has not yet begun.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "Resilience and self-awareness become critical. The gap between excitement and the grind of execution reveals itself here. Burnout Stage 1 is most common in this range.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Delegation anxiety and identity fusion become the key issues — founders who cannot let go of control create the ceiling for their company. Decision-making quality under scale pressure is tested.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Leadership identity and CEO evolution. The founder must shift from doer to architect. Those who cannot make this transition personally will stall the business regardless of market opportunity.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Legacy mindset, succession thinking, and sustained purpose. Burnout is a risk even here — founders who built too much of their identity into the company struggle at this stage.", "stage_group": "Stage 1→10+"}]', '35.00', 'A score below 35% in this pillar triggers Section H (Psychological State Note) in the Founder Clarity Report regardless of all other scores. The report will acknowledge the emotional reality before presenting any business diagnosis.') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "pillar_name", "pillar_description", "pillar_weightage", "pillar_order", "created_at", "updated_at", "what_falls_under", "score_bands", "stage_behaviour", "red_flag_threshold", "red_flag_note") values ('2', 'Market Clarity', 'Measures how well the founder understands the problem they are solving, who they are solving it for, and whether there is real evidence of demand. Covers customer discovery, ICP definition, competitive awareness, value proposition, and go-to-market strategy.', '20.00', '2', '2026-07-10 11:15:56.284048+00', '2026-07-26 05:27:23.650751+00', '["Problem clarity — can the founder articulate the pain clearly and specifically", "Customer discovery — have they spoken to real potential customers outside their network", "Ideal Customer Profile (ICP) — is the target customer specific and well-defined", "Demand validation — is there evidence that people want this, not just believe they do", "Competitive awareness — do they know what alternatives exist and why theirs is better", "Value proposition — can they articulate why a customer would switch to their solution", "Go-to-market strategy — do they have a structured path to reaching and acquiring customers", "Positioning — do they know where they sit in the market and how to communicate that"]', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "The founder is building for an assumed customer with an assumed problem and no real evidence. They cannot define their ICP, have not done customer discovery, or believe everyone is their customer. This is the most dangerous state — they are burning time and money on assumptions."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The founder has done some discovery but has not gone deep enough. They have a general sense of the customer but lack specificity. Their GTM is vague. They may have spoken to people who liked the idea but cannot point to evidence that those people would pay."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "The founder has a defined ICP, has done real customer interviews, and understands the competitive landscape reasonably well. Their GTM has a structure but may not yet be tested. They can articulate the value proposition clearly."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "The founder has deep, validated market knowledge. They can name their ideal customer precisely, have evidence of demand (not opinion), understand exactly why customers would switch, and have a clear channel strategy based on real data not assumptions."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Problem and customer hypothesis are the primary measures. At this stage lack of market clarity is normal and expected — the goal is identifying it early so it gets addressed before building begins.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "Customer discovery must happen here. Founders who skip this and build on assumptions surface in diagnosis with strong product scores but weak market clarity — a common and costly pattern.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "ICP precision and channel consistency become critical. Early GTM approaches that worked on hustle need to become systematic. Founders who have not refined their ICP hit a ceiling here.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Market expansion strategy and new segment entry. The original ICP may be saturating and the founder needs clarity on adjacent markets, international expansion, or product-line extension.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Category creation and market leadership. The founder is no longer finding a market — they are shaping one.", "stage_group": "Stage 1→10+"}]', '35.00', 'Scores below 35% in Market Clarity combined with Stage 3 or above is a critical signal — the founder has been building without validating. This combination triggers a deep-dive in the Idea & Validation and GTM diagnostic categories.') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "pillar_name", "pillar_description", "pillar_weightage", "pillar_order", "created_at", "updated_at", "what_falls_under", "score_bands", "stage_behaviour", "red_flag_threshold", "red_flag_note") values ('3', 'Revenue Maturity', 'Measures how deliberately the founder builds and manages the commercial engine of their business. Covers pricing strategy, sales process, pipeline management, unit economics, customer retention, revenue predictability, and financial planning.', '20.00', '3', '2026-07-10 11:15:56.284048+00', '2026-07-26 05:27:23.650751+00', '["Sales process — is there a structured, repeatable process for acquiring customers", "Pipeline management — does the founder know what is in their pipeline and what will close", "Pricing strategy — is pricing based on value and data, not gut feel or cost-plus", "Unit economics — does the founder know their CAC, LTV, gross margin, and payback period", "Revenue retention — are customers staying and expanding, or churning", "Revenue predictability — is revenue recurring, contractual, or entirely project-based", "Financial planning — does the founder have a financial model and cash flow forecast", "Revenue model fit — does the revenue model match the business and market reality"]', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "The founder has no sales process, does not know their unit economics, prices by instinct, and has no revenue predictability. If they have revenue, it is accidental not engineered. Cash may be running out faster than they realise."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The founder is making some sales but does not have a repeatable process. They underprice consistently, do not track pipeline, and have never modelled their unit economics. Growth is happening but is fragile and dependent on founder hustle."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "The founder has a defined sales process, reasonable pricing awareness, and some understanding of unit economics. Revenue is growing with some predictability. Retention is tracked. They are moving from reactive to proactive on revenue management."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "The founder manages revenue like a system. They have a healthy pipeline, value-based pricing, strong unit economics, high retention, and a financial model they update regularly. Revenue is predictable and the founder knows exactly what needs to happen to grow it."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Revenue Maturity is not expected at this stage. The score here measures intent — whether the founder has thought about how they will make money and for whom. Pre-revenue is normal and fine.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "First revenue and initial sales learnings. The founder should be actively selling, not waiting for the product to be perfect. Low scores here indicate sales avoidance — one of the most common founder blind spots.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Unit economics become critical. Revenue growing without understanding LTV:CAC or gross margin is a ticking clock. This is where many Indian startups discover they have been growing unprofitably.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Revenue operations and predictability. The sales motion must be scalable — repeatable by people who are not the founder. Revenue retention (NRR) becomes more important than acquisition.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Capital efficiency and sustainable growth. The question shifts from how do we grow to how do we grow without destroying value in the process.", "stage_group": "Stage 1→10+"}]', '40.00', 'A founder at Stage 4 or above with a Revenue Maturity score below 40% is a high-priority signal. At that stage, revenue systems should exist. Their absence indicates the business may be surviving on funding or founder relationships rather than commercial viability.') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "pillar_name", "pillar_description", "pillar_weightage", "pillar_order", "created_at", "updated_at", "what_falls_under", "score_bands", "stage_behaviour", "red_flag_threshold", "red_flag_note") values ('4', 'Product & Execution', 'Measures the founder''s ability to build the right thing and build it well. Covers product-market fit signals, development discipline, user feedback loops, prioritisation rigour, operational systems, and execution consistency.', '15.00', '4', '2026-07-10 11:15:56.284048+00', '2026-07-26 05:27:23.650751+00', '["Product-market fit signals — are users getting real value and staying", "Build discipline — does the founder avoid feature bloat and build the minimum valuable thing", "Feedback loops — are real users informing product decisions regularly", "Prioritisation — does the team know what to build next and why", "Technical quality — is the product stable, scalable, and maintainable", "Operational systems — are there processes, SOPs, and tools that enable consistent delivery", "Execution velocity — can the team ship and iterate fast enough to learn", "Quality management — does the team catch problems before customers do"]', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "The product is either not built, not working, or not delivering real value to users. Execution is chaotic — no clear processes, constant firefighting, everything depends on the founder. At this level the business cannot scale even with good market clarity and revenue."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The product works but is fragile. There are feedback loops but they are informal. Prioritisation is reactive rather than strategic. Execution depends heavily on individual heroics rather than systems. Technical debt is accumulating."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "The product delivers clear value with reasonable reliability. There is a feedback mechanism with real users. Prioritisation has some structure. Processes exist for core operations. The team can execute without the founder being involved in every decision."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "The product has strong PMF signals. Development is disciplined, data-informed, and customer-centric. The team executes consistently through systems not heroics. Quality is managed proactively. The product roadmap is clear and defensible."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Execution is about idea development and prototyping. Low scores are expected and acceptable. The signal being measured is whether the founder understands the difference between building and validating.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "MVP quality and feedback loop discipline. Founders who build too much too fast without talking to users surface here with low product maturity despite high engineering effort. The MVP trap is most common at Stage 2.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Product-market fit must be demonstrated here. Execution systems and quality management become critical as the team grows beyond the founder''s direct oversight.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Product operations and platform thinking. The product must now serve multiple customer segments without custom engineering for each. Architecture decisions made in earlier stages become constraints here.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Product portfolio management and innovation pipeline. The original product is mature — the challenge is staying relevant while managing what exists.", "stage_group": "Stage 1→10+"}]', '35.00', 'A score below 35% in Product & Execution at Stage 3 or above signals that the founder has been building without a reliable feedback loop or execution system. This is a critical gap that blocks all other growth.') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "pillar_name", "pillar_description", "pillar_weightage", "pillar_order", "created_at", "updated_at", "what_falls_under", "score_bands", "stage_behaviour", "red_flag_threshold", "red_flag_note") values ('5', 'Team & Leadership', 'Measures the founder''s ability to build, lead, and retain the team needed to execute their vision. Covers co-founder dynamics, hiring quality, delegation maturity, communication culture, accountability systems, and the founder''s evolution from operator to leader.', '10.00', '5', '2026-07-10 11:15:56.284048+00', '2026-07-26 05:27:23.650751+00', '["Co-founder alignment — do co-founders have complementary skills, clear roles, and shared vision", "Hiring quality — are people hired for demonstrated ability or familiarity and hope", "Delegation — can the founder let go of tasks and trust others to execute", "Communication — does the team have clarity on priorities, context, and expectations", "Accountability — are there systems for tracking commitments and addressing gaps", "Culture — is the work environment one where people can do their best work and speak honestly", "Conflict resolution — are disagreements addressed constructively or avoided until they explode", "Leadership evolution — is the founder growing as a leader as the company grows"]', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "The team is dysfunctional, misaligned, or non-existent. Co-founder conflict may be present. The founder micro-manages everything or has the wrong people in key roles. Attrition is high or about to be. This pillar at this level is often the hidden cause of slow execution across every other pillar."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The team is functional but fragile. The founder is still doing too much. Delegation is uncomfortable. Key roles may have skill gaps that are being papered over. Communication is informal and inconsistent. The team works hard but not always in the same direction."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "The team has reasonable clarity on roles and priorities. The founder is starting to delegate meaningfully. Accountability exists in some form. Culture is healthy enough that people speak up. Some gaps in talent remain but the team is directionally right."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "The team is high-performing, well-aligned, and capable of executing without the founder in every conversation. Hiring is disciplined. Delegation is genuine. The culture enables honest conversation and fast course-correction. The founder is growing as a leader alongside the company."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Team is usually just the founder. This pillar measures co-founder selection thinking, awareness of skill gaps, and whether the founder knows what kind of people they need to recruit.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "First hires and co-founder dynamics are tested. Early hiring mistakes are common and recoverable. The key signal is whether the founder is hiring for skill fit or emotional comfort.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Delegation becomes the critical test. Founders who cannot let go create bottlenecks that limit the entire company''s pace. Manager development and accountability systems become essential.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Organisational design and leadership pipeline. The founder is now managing managers. The original team that built the company may not be the right team to scale it — this is one of the most difficult personal realities a founder faces.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Succession planning and institutional culture. The leader is building something that can outlast their direct involvement.", "stage_group": "Stage 1→10+"}]', '35.00', 'A score below 35% in Team & Leadership at Stage 4 or above is a serious signal. By Stage 4, the founder cannot do everything themselves. A team that is dysfunctional or misaligned at this stage will cap the entire company''s growth regardless of how strong the other pillars are.') on conflict do nothing;
insert into "readiness_pillars" ("pillar_id", "pillar_name", "pillar_description", "pillar_weightage", "pillar_order", "created_at", "updated_at", "what_falls_under", "score_bands", "stage_behaviour", "red_flag_threshold", "red_flag_note") values ('6', 'Strategic Clarity', 'Measures whether the founder has a coherent, defensible plan for where they are going and how they will get there. Covers vision articulation, goal quality, decision-making frameworks, competitive strategy, capital planning, and the ability to prioritise ruthlessly.', '10.00', '6', '2026-07-10 11:15:56.284048+00', '2026-07-26 05:27:23.650751+00', '["Vision clarity — can the founder articulate where they are going and why it matters", "Goal quality — are goals specific, measurable, realistic, and time-bound", "Decision-making frameworks — does the founder have principles that guide hard choices", "Competitive strategy — do they know how they will win and sustain their advantage", "Capital strategy — do they know when to raise, how much, and from whom", "Prioritisation — can they say no to good opportunities to focus on great ones", "Scenario planning — have they thought about what happens if key assumptions are wrong", "Milestones — are there clear markers that tell them if the strategy is working"]', '[{"level": "Critical Gap", "range_max": 35, "range_min": 0, "description": "The founder is operating without a coherent strategic direction. They are reactive, chasing opportunities without a framework for deciding which to pursue. They cannot articulate a defensible competitive position or a realistic path to their stated goals. Every decision feels equally important because nothing has been prioritised."}, {"level": "Needs Attention", "range_max": 55, "range_min": 36, "description": "The founder has a vision but it is vague and their goals are either too ambitious or not measurable. They have not thought through their competitive moat. Their capital strategy is reactive. They say yes to too many things because they have not defined what they are truly optimising for."}, {"level": "Developing", "range_max": 75, "range_min": 56, "description": "The founder has a clear direction, realistic goals, and some framework for making trade-offs. They understand their competitive position reasonably well. Their capital thinking has structure. They can articulate what success looks like in 12 months."}, {"level": "Strong", "range_max": 100, "range_min": 76, "description": "The founder thinks and acts strategically. They have a compelling vision, specific measurable goals, a clear competitive strategy, and a capital plan that is connected to milestones. They say no with confidence. They think in scenarios and update their strategy when reality diverges from assumptions."}]', '[{"stage": "Ideation (Stage 1)", "stage_id": 1, "description": "Strategic Clarity is mostly about idea conviction and initial market hypothesis. Low scores are expected. The signal is whether the founder has thought about why their timing is right and what makes them the right person.", "stage_group": "Stage 0"}, {"stage": "Validation to Prototype/MVP (Stages 2-3)", "stage_id": "2-3", "description": "Milestone clarity and early prioritisation. The founder must be able to articulate what they need to prove in the next 90 days and why that matters for the company''s survival and growth.", "stage_group": "Stage 0→1"}, {"stage": "Early Traction to Growth/Scaling (Stages 4-5)", "stage_id": "4-5", "description": "Competitive positioning and capital strategy become critical. The founder must know where they are playing, where they are not playing, and how they will defend their position as competition increases.", "stage_group": "Spans Stage 0→1 and Stage 1→10+"}, {"stage": "Expansion to Maturity (Stages 6-7)", "stage_id": "6-7", "description": "Portfolio thinking and organisational strategy. The founder must balance the demands of the current core business with the need to innovate and build for the future simultaneously.", "stage_group": "Stage 1→10+"}, {"stage": "Exit (Stage 8)", "stage_id": 8, "description": "Category creation and long-term institutional strategy. The founder is now setting direction for an organisation, not just a product.", "stage_group": "Stage 1→10+"}]', '35.00', 'A score below 35% in Strategic Clarity at Stage 4 or above is a serious signal. At earlier stages low strategic clarity is acceptable and normal. At Stage 4 and beyond, the absence of strategic direction means the business is growing without a compass — every new opportunity creates noise rather than momentum.') on conflict do nothing;
